// Step 1: Create feature branch and commit changes
git checkout -b feature/add-order-validation
// ... make code changes ...
git add src/main/java/com/example/OrderService.java
git commit -m "Add order validation for negative quantities"
git push origin feature/add-order-validation

// Step 2: Open PR on GitHub (via web UI)
// Title: "Add order validation for negative quantities"
// Description: "Fixes #123 - Prevents orders with qty < 0 from being created"

// Step 3: Reviewer comments on specific line
// "Should we also validate qty > 1000 for bulk order limits?"

// Step 4: Address feedback, push new commit
git add src/main/java/com/example/OrderService.java
git commit -m "Add upper bound validation for bulk orders"
git push origin feature/add-order-validation
// The PR automatically updates with the new commit

// Step 5: Reviewer approves, merge PR via GitHub UI
// GitHub creates merge commit or squashes commits based on team settings

// Scenario: Reviewer asked you to add null checks and extract a method

// STEP 1: Make the requested changes locally
public class OrderService {

    public void processOrder(Order order) {
        if (order == null || order.getItems().isEmpty()) {  // Added null check per review
            throw new IllegalArgumentException("Invalid order");
        }

        validateInventory(order);  // Extracted method per review comment
        calculateTotal(order);
        saveOrder(order);
    }

    private void validateInventory(Order order) {  // New extracted method
        for (var item : order.getItems()) {
            if (!inventoryService.hasStock(item)) {
                throw new OutOfStockException(item.getName());
            }
        }
    }
}

// STEP 2: Commit with a descriptive message
// $ git add src/main/java/com/example/OrderService.java
// $ git commit -m "Add null checks and extract validateInventory method"

// STEP 3: Push to the same branch (updates PR automatically)
// $ git push origin feature/order-processing

// STEP 4: Reply in the PR comment thread
// "Good catch! Added null check at line 8 and extracted inventory
// validation into its own method at line 15. Let me know if this
// addresses your concern."

// Scenario: feature branch with 3 commits
// main branch:     A---B
// feature branch:      C---D---E

// Strategy 1: MERGE COMMIT (default)
git checkout main
git merge feature/add-validation
// Result: A---B-------M
//              \     /
//               C---D---E
// Merge commit M preserves full branch history, all commits visible

// Strategy 2: SQUASH AND MERGE
git checkout main
git merge --squash feature/add-validation
git commit -m "Add order validation (PR #45)"
// Result: A---B---S
// Single commit S contains all changes from C, D, E combined
// Original commits C, D, E not in main history

// Strategy 3: REBASE AND MERGE
git checkout feature/add-validation
git rebase main
git checkout main
git merge feature/add-validation  // fast-forward merge
// Result: A---B---C'---D'---E'
// Commits replayed linearly, no merge commit
// C', D', E' are new commits (different hashes) with same changes
